BEGIN;

-- Reviewed public-source registry for the portfolio assistant. The assistant
-- route serves a chunk only when its source AND exact version are both the
-- active registry version here and the independently reviewed version in
-- lib/server/reviewed-sources.ts. Rows are additive; disabling a source is an
-- UPDATE to status, never a DELETE of indexed history.
CREATE TABLE IF NOT EXISTS public.portfolio_assistant_source_registry (
    source_id TEXT PRIMARY KEY,
    source_version TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'ready',
    title TEXT,
    source_url TEXT,
    chunk_count INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT portfolio_assistant_registry_status_check
      CHECK (status IN ('ready', 'disabled')),
    CONSTRAINT portfolio_assistant_registry_chunk_count_check
      CHECK (chunk_count >= 0)
);

